using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;

namespace ContosoUniversity.Tests.Controllers
{
    public class InstructorsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly InstructorsController _controller;

        public InstructorsControllerTests()
        {
            _context = TestDbContextFactory.Create();
            _controller = new InstructorsController(_context);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        private Instructor CreateTestInstructor(string firstName = "Kim", string lastName = "Abercrombie", DateTime? hireDate = null)
        {
            var instructor = new Instructor
            {
                FirstMidName = firstName,
                LastName = lastName,
                HireDate = hireDate ?? new DateTime(2000, 1, 1),
                CourseAssignments = new List<CourseAssignment>()
            };
            _context.Instructors.Add(instructor);
            _context.SaveChanges();
            return instructor;
        }

        private Course CreateTestCourse(int courseId, string title = "Test Course")
        {
            var dept = new Department
            {
                Name = "TestDept",
                Budget = 100000,
                StartDate = new DateTime(2020, 1, 1)
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var course = new Course
            {
                CourseID = courseId,
                Title = title,
                Credits = 3,
                DepartmentID = dept.DepartmentID,
                Enrollments = new List<Enrollment>()
            };
            _context.Courses.Add(course);
            _context.SaveChanges();
            return course;
        }

        #region Index Tests

        [Fact]
        public void Index_NoParams_ReturnsViewWithInstructors()
        {
            CreateTestInstructor("Kim", "Abercrombie");
            CreateTestInstructor("Fadi", "Fakhouri");

            var result = _controller.Index(null, null) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<ContosoUniversity.Models.SchoolViewModels.InstructorIndexData>(result.Model);
            Assert.Equal(2, model.Instructors.Count());
        }

        [Fact]
        public void Index_InstructorsOrderedByLastName()
        {
            CreateTestInstructor("Zach", "Zappa");
            CreateTestInstructor("Alice", "Anderson");

            var result = _controller.Index(null, null) as ViewResult;

            var model = Assert.IsType<ContosoUniversity.Models.SchoolViewModels.InstructorIndexData>(result!.Model);
            var list = model.Instructors.ToList();
            Assert.Equal("Anderson", list[0].LastName);
            Assert.Equal("Zappa", list[1].LastName);
        }

        [Fact]
        public void Index_WithInstructorId_ShowsCourses()
        {
            var instructor = CreateTestInstructor();
            var course = CreateTestCourse(1001, "Chemistry");
            var assignment = new CourseAssignment { InstructorID = instructor.ID, CourseID = course.CourseID };
            _context.CourseAssignments.Add(assignment);
            _context.SaveChanges();

            // Reload instructor with relationships
            _context.Entry(instructor).Collection(i => i.CourseAssignments).Load();

            var result = _controller.Index(instructor.ID, null) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<ContosoUniversity.Models.SchoolViewModels.InstructorIndexData>(result.Model);
            Assert.NotNull(model.Courses);
            Assert.Contains(model.Courses, c => c.Title == "Chemistry");
        }

        #endregion

        #region Details Tests

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            var result = _controller.Details(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Details_NotFound_ReturnsNotFound()
        {
            var result = _controller.Details(9999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Details_ValidId_ReturnsViewWithInstructor()
        {
            var instructor = CreateTestInstructor("Roger", "Harui");

            var result = _controller.Details(instructor.ID) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Instructor>(result.Model);
            Assert.Equal("Roger", model.FirstMidName);
            Assert.Equal("Harui", model.LastName);
        }

        #endregion

        #region Create Tests

        [Fact]
        public void Create_Get_ReturnsViewWithInstructor()
        {
            var result = _controller.Create() as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Instructor>(result.Model);
            Assert.NotNull(model.CourseAssignments);
        }

        [Fact]
        public void Create_Post_ValidInstructor_RedirectsToIndex()
        {
            var instructor = new Instructor
            {
                FirstMidName = "New",
                LastName = "Instructor",
                HireDate = new DateTime(2023, 1, 1),
                CourseAssignments = new List<CourseAssignment>()
            };

            var result = _controller.Create(instructor, null!);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }

        [Fact]
        public void Create_Post_ValidInstructor_SavesToDB()
        {
            var instructor = new Instructor
            {
                FirstMidName = "Saved",
                LastName = "Person",
                HireDate = new DateTime(2023, 6, 1),
                CourseAssignments = new List<CourseAssignment>()
            };

            _controller.Create(instructor, null!);

            var saved = _context.Instructors.FirstOrDefault(i => i.LastName == "Person");
            Assert.NotNull(saved);
            Assert.Equal("Saved", saved.FirstMidName);
        }

        [Fact]
        public void Create_Post_WithSelectedCourses_AssignsCourses()
        {
            var course = CreateTestCourse(2001, "Math");
            var instructor = new Instructor
            {
                FirstMidName = "Test",
                LastName = "WithCourses",
                HireDate = new DateTime(2023, 1, 1),
                CourseAssignments = new List<CourseAssignment>()
            };

            _controller.Create(instructor, new[] { "2001" });

            var saved = _context.Instructors.FirstOrDefault(i => i.LastName == "WithCourses");
            Assert.NotNull(saved);
            Assert.Single(saved.CourseAssignments);
            Assert.Equal(2001, saved.CourseAssignments.First().CourseID);
        }

        [Fact]
        public void Create_Post_InvalidModelState_ReturnsView()
        {
            _controller.ModelState.AddModelError("LastName", "Required");
            var instructor = new Instructor
            {
                FirstMidName = "X",
                LastName = "",
                HireDate = DateTime.Today,
                CourseAssignments = new List<CourseAssignment>()
            };

            var result = _controller.Create(instructor, null!) as ViewResult;

            Assert.NotNull(result);
        }

        #endregion

        #region Delete Tests

        [Fact]
        public void Delete_Get_NullId_ReturnsBadRequest()
        {
            var result = _controller.Delete(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Delete_Get_NotFound_ReturnsNotFound()
        {
            var result = _controller.Delete(9999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Delete_Get_ValidId_ReturnsView()
        {
            var instructor = CreateTestInstructor("Del", "Table");

            var result = _controller.Delete(instructor.ID) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Instructor>(result.Model);
            Assert.Equal("Table", model.LastName);
        }

        [Fact]
        public void DeleteConfirmed_RemovesInstructorAndRedirects()
        {
            var instructor = CreateTestInstructor("Rem", "Oved");
            instructor.OfficeAssignment = new OfficeAssignment { InstructorID = instructor.ID, Location = "Room 1" };
            _context.SaveChanges();

            var result = _controller.DeleteConfirmed(instructor.ID);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Null(_context.Instructors.Find(instructor.ID));
        }

        [Fact]
        public void DeleteConfirmed_ClearsDepartmentAdministrator()
        {
            var instructor = CreateTestInstructor("Admin", "Instructor");
            instructor.OfficeAssignment = null;
            var dept = new Department
            {
                Name = "WithAdmin",
                Budget = 50000,
                StartDate = new DateTime(2020, 1, 1),
                InstructorID = instructor.ID
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            _controller.DeleteConfirmed(instructor.ID);

            var updatedDept = _context.Departments.Find(dept.DepartmentID);
            Assert.NotNull(updatedDept);
            Assert.Null(updatedDept.InstructorID);
        }

        #endregion
    }
}

