using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.EntityFrameworkCore;

namespace ContosoUniversity.Tests.Data
{
    public class SchoolContextTests : IDisposable
    {
        private readonly SchoolContext _context;

        public SchoolContextTests()
        {
            _context = TestDbContextFactory.Create();
        }

        public void Dispose()
        {
            _context.Dispose();
        }

        [Fact]
        public void CanAddAndRetrieveStudent()
        {
            var student = new Student
            {
                FirstMidName = "Test",
                LastName = "Student",
                EnrollmentDate = new DateTime(2023, 9, 1)
            };
            _context.Students.Add(student);
            _context.SaveChanges();

            var retrieved = _context.Students.Find(student.ID);
            Assert.NotNull(retrieved);
            Assert.Equal("Test", retrieved.FirstMidName);
            Assert.Equal("Student", retrieved.LastName);
        }

        [Fact]
        public void CanAddAndRetrieveInstructor()
        {
            var instructor = new Instructor
            {
                FirstMidName = "Prof",
                LastName = "Teacher",
                HireDate = new DateTime(2000, 1, 1),
                CourseAssignments = new List<CourseAssignment>()
            };
            _context.Instructors.Add(instructor);
            _context.SaveChanges();

            var retrieved = _context.Instructors.Find(instructor.ID);
            Assert.NotNull(retrieved);
            Assert.Equal("Prof", retrieved.FirstMidName);
        }

        [Fact]
        public void CanAddDepartmentWithInstructor()
        {
            var instructor = new Instructor
            {
                FirstMidName = "Admin",
                LastName = "Person",
                HireDate = new DateTime(2000, 1, 1),
                CourseAssignments = new List<CourseAssignment>()
            };
            _context.Instructors.Add(instructor);
            _context.SaveChanges();

            var dept = new Department
            {
                Name = "Science",
                Budget = 200000,
                StartDate = new DateTime(2020, 1, 1),
                InstructorID = instructor.ID
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var retrieved = _context.Departments.Include(d => d.Administrator)
                .FirstOrDefault(d => d.DepartmentID == dept.DepartmentID);
            Assert.NotNull(retrieved);
            Assert.Equal("Science", retrieved.Name);
            Assert.NotNull(retrieved.Administrator);
            Assert.Equal("Admin", retrieved.Administrator.FirstMidName);
        }

        [Fact]
        public void CanAddCourseWithDepartment()
        {
            var dept = new Department
            {
                Name = "Math",
                Budget = 100000,
                StartDate = new DateTime(2020, 1, 1)
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var course = new Course
            {
                CourseID = 1001,
                Title = "Algebra",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };
            _context.Courses.Add(course);
            _context.SaveChanges();

            var retrieved = _context.Courses.Include(c => c.Department)
                .FirstOrDefault(c => c.CourseID == 1001);
            Assert.NotNull(retrieved);
            Assert.Equal("Algebra", retrieved.Title);
            Assert.Equal("Math", retrieved.Department.Name);
        }

        [Fact]
        public void CanCreateEnrollment()
        {
            var student = new Student
            {
                FirstMidName = "Enrolled",
                LastName = "Student",
                EnrollmentDate = new DateTime(2023, 1, 1)
            };
            _context.Students.Add(student);

            var dept = new Department { Name = "Dept", Budget = 50000, StartDate = new DateTime(2020, 1, 1) };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var course = new Course { CourseID = 2001, Title = "Course", Credits = 3, DepartmentID = dept.DepartmentID };
            _context.Courses.Add(course);
            _context.SaveChanges();

            var enrollment = new Enrollment
            {
                StudentID = student.ID,
                CourseID = course.CourseID,
                Grade = Grade.A
            };
            _context.Enrollments.Add(enrollment);
            _context.SaveChanges();

            var retrieved = _context.Enrollments
                .Include(e => e.Student)
                .Include(e => e.Course)
                .FirstOrDefault(e => e.EnrollmentID == enrollment.EnrollmentID);
            Assert.NotNull(retrieved);
            Assert.Equal(Grade.A, retrieved.Grade);
            Assert.Equal("Enrolled", retrieved.Student.FirstMidName);
            Assert.Equal("Course", retrieved.Course.Title);
        }

        [Fact]
        public void CourseAssignment_CompositeKey_Works()
        {
            var instructor = new Instructor
            {
                FirstMidName = "Test",
                LastName = "Inst",
                HireDate = new DateTime(2000, 1, 1),
                CourseAssignments = new List<CourseAssignment>()
            };
            _context.Instructors.Add(instructor);

            var dept = new Department { Name = "D", Budget = 50000, StartDate = new DateTime(2020, 1, 1) };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var course = new Course { CourseID = 3001, Title = "C", Credits = 3, DepartmentID = dept.DepartmentID };
            _context.Courses.Add(course);
            _context.SaveChanges();

            var assignment = new CourseAssignment { CourseID = 3001, InstructorID = instructor.ID };
            _context.CourseAssignments.Add(assignment);
            _context.SaveChanges();

            var retrieved = _context.CourseAssignments.Find(3001, instructor.ID);
            Assert.NotNull(retrieved);
        }

        [Fact]
        public void CanAddOfficeAssignment()
        {
            var instructor = new Instructor
            {
                FirstMidName = "Office",
                LastName = "Worker",
                HireDate = new DateTime(2000, 1, 1),
                CourseAssignments = new List<CourseAssignment>()
            };
            _context.Instructors.Add(instructor);
            _context.SaveChanges();

            var office = new OfficeAssignment
            {
                InstructorID = instructor.ID,
                Location = "Room 101"
            };
            _context.OfficeAssignments.Add(office);
            _context.SaveChanges();

            var retrieved = _context.OfficeAssignments.Find(instructor.ID);
            Assert.NotNull(retrieved);
            Assert.Equal("Room 101", retrieved.Location);
        }

        [Fact]
        public void PersonFullName_ReturnsLastNameCommaFirst()
        {
            var student = new Student
            {
                FirstMidName = "John",
                LastName = "Doe",
                EnrollmentDate = DateTime.Today
            };

            Assert.Equal("Doe, John", student.FullName);
        }
    }

    public class DbInitializerTests
    {
        [Fact]
        public void Initialize_SeedsData_WhenEmpty()
        {
            using var context = TestDbContextFactory.Create();

            DbInitializer.Initialize(context);

            Assert.True(context.Students.Any());
            Assert.True(context.Instructors.Any());
            Assert.True(context.Departments.Any());
            Assert.True(context.Courses.Any());
            Assert.True(context.Enrollments.Any());
            Assert.True(context.CourseAssignments.Any());
            Assert.True(context.OfficeAssignments.Any());
        }

        [Fact]
        public void Initialize_DoesNotReSeed_WhenStudentsExist()
        {
            using var context = TestDbContextFactory.Create();
            context.Students.Add(new Student
            {
                FirstMidName = "Existing",
                LastName = "Student",
                EnrollmentDate = DateTime.Today
            });
            context.SaveChanges();

            DbInitializer.Initialize(context);

            // Should still have only 1 student
            Assert.Equal(1, context.Students.Count());
        }

        [Fact]
        public void Initialize_Seeds8Students()
        {
            using var context = TestDbContextFactory.Create();

            DbInitializer.Initialize(context);

            Assert.Equal(8, context.Students.Count());
        }

        [Fact]
        public void Initialize_Seeds5Instructors()
        {
            using var context = TestDbContextFactory.Create();

            DbInitializer.Initialize(context);

            Assert.Equal(5, context.Instructors.Count());
        }

        [Fact]
        public void Initialize_Seeds4Departments()
        {
            using var context = TestDbContextFactory.Create();

            DbInitializer.Initialize(context);

            Assert.Equal(4, context.Departments.Count());
        }

        [Fact]
        public void Initialize_Seeds7Courses()
        {
            using var context = TestDbContextFactory.Create();

            DbInitializer.Initialize(context);

            Assert.Equal(7, context.Courses.Count());
        }
    }
}

